{
  "name": "传感器轮询线程",
  "name_en": "Sensor Polling Thread",
  "manufacturer": "",
  "description": "用于实验自动化系统中的非物理软件线程组件，负责在后台周期性轮询传感器读数，并管理读数缓冲区与线程生命周期。",
  "description_en": "A non-physical software thread component used in laboratory automation to poll sensor readings in the background and manage the reading buffer and thread lifecycle.",
  "actions": [
    {
      "action_name": "auto-read",
      "description": "执行一次传感器读取或轮询操作。",
      "description_en": "Perform one sensor read or polling operation."
    },
    {
      "action_name": "auto-read_load_buffer",
      "description": "读取当前缓冲区中已采集的传感器数据。",
      "description_en": "Read the sensor data currently stored in the acquisition buffer."
    },
    {
      "action_name": "auto-reset_load_buffer",
      "description": "重置或清空传感器数据缓冲区。",
      "description_en": "Reset or clear the sensor data buffer."
    },
    {
      "action_name": "auto-terminate",
      "description": "终止后台传感器轮询线程。",
      "description_en": "Terminate the background sensor polling thread."
    },
    {
      "action_name": "auto-alive",
      "description": "检查轮询线程是否仍在运行。",
      "description_en": "Check whether the polling thread is still running."
    },
    {
      "action_name": "auto-run",
      "description": "运行线程主循环以持续轮询传感器。",
      "description_en": "Run the thread main loop to continuously poll the sensor."
    }
  ],
  "tag_hints": [
    "sensor polling",
    "background thread",
    "data buffering",
    "asynchronous acquisition",
    "experiment automation",
    "thread lifecycle"
  ]
}

